(
  $q$07660dc1-73e4-4ad1-8d8c-440bf9a19e8d$q$::uuid, $q$kleenbot-c30-robot-limpieza-autonoma-ref-c30-keenon$q$, $q$KEENON-KLEENBOT-C30$q$, $q$d026ac8a-6d63-4fb7-8953-a7aa7a32e627$q$::uuid, $q$3e2982dc-eebb-4eb4-912e-087e2b08f3c7$q$::uuid,
  $q$KLEENBOT C30 Robot de Limpieza Autónoma$q$, $q$KLEENBOT C30 Autonomous Cleaning Robot$q$, $q$Robot de limpieza autónoma para pisos duros interiores y alfombra de pelo bajo, con aspirado, barrido y mopa seca, hasta 600 m²/h.$q$, $q$Autonomous cleaning robot for indoor hard floors and low-pile carpet, with vacuuming, sweeping and dust mopping, up to 600 m²/h.$q$,
  $q$KLEENBOT C30 es un robot de limpieza autónoma para ambientes interiores. Combina los modos de barrido, aspirado y mopa seca con un cepillo de rodillo de 610 mm y una succión de hasta 19.000 Pa. Su batería LFP de 25,6 V y 28,5 Ah ofrece entre 3 y 6 horas de operación en barrido y aspirado, y hasta 10 horas en mopa seca. Se carga automáticamente en la base de carga incluida.$q$, $q$KLEENBOT C30 is an autonomous cleaning robot for indoor spaces. It combines sweeping, vacuuming and dust-mopping modes with a 610 mm roller brush and suction of up to 19,000 Pa. Its 25.6 V, 28.5 Ah LFP battery gives 3 to 6 hours of operation in sweeping and vacuuming, and up to 10 hours in dust-mopping mode. It charges automatically at the bundled charging dock.$q$, $j$[{"clave":"Modos de limpieza","valor":"Barrido; aspirado (barrido + aspirado); mopa seca (empuje de polvo)","grupo":"Rendimiento"},{"clave":"Eficiencia de limpieza","valor":"Hasta 600 m²/h","grupo":"Rendimiento"},{"clave":"Área de limpieza","valor":"Hasta 2.500 m² por tarea (con carga completa)","grupo":"Rendimiento"},{"clave":"Succión","valor":"Hasta 19.000 Pa","grupo":"Rendimiento"},{"clave":"Ancho máximo de limpieza","valor":"610 mm (dos cepillos laterales + cepillo de rodillo)","grupo":"Rendimiento"},{"clave":"Recolección de polvo","valor":"3,5 L por bolsa","grupo":"Rendimiento"},{"clave":"Autonomía","valor":"3 a 6 h en barrido y aspirado; hasta 10 h en mopa seca","grupo":"Rendimiento"},{"clave":"Ruido","valor":"≤ 70 dB","grupo":"Rendimiento"},{"clave":"Velocidad máxima de desplazamiento","valor":"0,8 m/s","grupo":"Rendimiento"},{"clave":"Distancia de frenado","valor":"50 cm","grupo":"Rendimiento"},{"clave":"Altura de obstáculos superables","valor":"20 mm","grupo":"Rendimiento"},{"clave":"Alfombra","valor":"Hasta 10 mm de pelo","grupo":"Rendimiento"},{"clave":"Pendiente","valor":"≤ 8°","grupo":"Rendimiento"},{"clave":"Batería","valor":"LFP, 25,6 V, 28,5 Ah","grupo":"Batería y carga"},{"clave":"Carga","valor":"Automática con la base de carga incluida","grupo":"Batería y carga"},{"clave":"Entrada de carga","valor":"100-240 V~, 50/60 Hz","grupo":"Batería y carga"},{"clave":"Tiempo de carga","valor":"5 a 6 h","grupo":"Batería y carga"},{"clave":"Material","valor":"ABS y aleación de aluminio","grupo":"Hardware y navegación"},{"clave":"Posicionamiento","valor":"Láser, precisión a nivel de centímetro","grupo":"Hardware y navegación"},{"clave":"Sensores","valor":"LiDAR (240°, alcance ≤ 25 m), visión estéreo (120°, 0,1-1,5 m), sensor de colisión, IMU","grupo":"Hardware y navegación"},{"clave":"Pantalla","valor":"7 pulgadas, 1024 × 600","grupo":"Hardware y navegación"},{"clave":"Conectividad","valor":"Wi-Fi 2,4 GHz","grupo":"Hardware y navegación"},{"clave":"Sistema operativo","valor":"Linux (control) y Android (interacción)","grupo":"Sistema"},{"clave":"Idiomas de la app","valor":"Chino, inglés, japonés, coreano, francés","grupo":"Sistema"},{"clave":"Funciones de la app","valor":"Limpieza inmediata, programada, manual y modo de enseñanza","grupo":"Sistema"},{"clave":"Operación","valor":"0 a 40 °C · 20 % a 80 % HR · interior, pisos duros y alfombra de pelo bajo ≤ 10 mm","grupo":"Ambiente"},{"clave":"Almacenamiento","valor":"-15 a 45 °C · 20 % a 80 % HR","grupo":"Ambiente"},{"clave":"Dimensiones del robot (An × Pr × Al)","valor":"490 × 610 × 750 mm con empujador de polvo; 490 × 520 × 750 mm sin empujador","grupo":"Dimensiones y peso"},{"clave":"Peso del robot","valor":"35 kg con batería; 30 kg sin batería","grupo":"Dimensiones y peso"},{"clave":"Base de carga (An × Pr × Al)","valor":"220 × 130 × 330 mm · 2,4 kg","grupo":"Dimensiones y peso"},{"clave":"Contenido de la caja","valor":"Robot ×1, base de carga ×1, manual ×1, cepillo lateral ×4, paño de mopa ×2, cepillo de rodillo ×2, raspador de cepillo de rodillo ×3, bolsa de polvo ×20, filtro HEPA ×1","grupo":"Incluye"},{"clave":"Consumibles disponibles","valor":"Cepillo lateral, paño de mopa, cepillo de rodillo, raspador, bolsa de polvo y filtro HEPA","grupo":"Incluye"},{"clave":"Color","valor":"Blanco perlado","grupo":"Incluye"}]$j$::jsonb,
  ARRAY[$q$Pisos duros interiores$q$, $q$Alfombras de pelo bajo de hasta 10 mm$q$, $q$Limpieza diaria de ambientes interiores$q$, $q$Limpieza programada desde la app$q$]::TEXT[], ARRAY[$q$Indoor hard floors$q$, $q$Low-pile carpets up to 10 mm$q$, $q$Daily cleaning of indoor spaces$q$, $q$Scheduled cleaning from the app$q$]::TEXT[], $q$/assets/productos/importados/kleenbot-c30-robot-limpieza-autonoma/robot-producto-kleenbot-c30.webp$q$, ARRAY[$q$/assets/productos/importados/kleenbot-c30-robot-limpieza-autonoma/robot-producto-kleenbot-c30.webp$q$]::TEXT[],
  $q$/assets/productos/importados/kleenbot-c30-robot-limpieza-autonoma/ficha-tecnica.pdf$q$, $j${"beneficios_es":["Aspirado, barrido y mopa seca en un solo equipo","Hasta 600 m²/h con 610 mm de ancho de limpieza","De 3 a 6 h de autonomía en barrido y aspirado; hasta 10 h en mopa seca","Navegación con LiDAR, visión estéreo y sensor de colisión","Pantalla de expresión de 7″ con luces y contenidos personalizables"],"beneficios_en":["Vacuuming, sweeping and dust-mopping in one machine","Up to 600 m²/h with a 610 mm cleaning width","3 to 6 h of runtime in sweeping and vacuuming; up to 10 h in dust-mopping","Navigation with LiDAR, stereo vision and a collision sensor","7-inch expression screen with lights and customizable content"],"valor_es":"KLEENBOT C30 automatiza la limpieza diaria de pisos duros interiores con limpieza programada desde la app, base de carga automática y consumibles de fácil reposición. Precio bajo cotización.","valor_en":"KLEENBOT C30 automates daily cleaning of indoor hard floors with scheduled cleaning from the app, an automatic charging dock and easy-to-replace consumables. Price on request.","seo_keywords_es":["KLEENBOT C30","C30 robot de limpieza","robot de limpieza autónoma","robot aspiradora y fregadora","robot de limpieza de pisos duros","robot de limpieza para oficinas","robot de limpieza interior","KEENON C30"],"seo_keywords_en":["KLEENBOT C30","C30 cleaning robot","autonomous cleaning robot","robot vacuum and mop","hard floor cleaning robot","office cleaning robot","indoor cleaning robot","KEENON C30"],"marca":"KEENON"}$j$::jsonb,
  'equipo', 'cotizacion', NULL, 'COP', true
