(
  $q$55677cde-1384-497f-a414-2ed463f230f3$q$::uuid, $q$kleenbot-c40-robot-limpieza-autonoma-ref-c40-keenon$q$, $q$KEENON-KLEENBOT-C40$q$, $q$d026ac8a-6d63-4fb7-8953-a7aa7a32e627$q$::uuid, $q$3e2982dc-eebb-4eb4-912e-087e2b08f3c7$q$::uuid,
  $q$KLEENBOT C40 Robot de Limpieza Autónoma 4 en 1$q$, $q$KLEENBOT C40 4-in-1 Autonomous Cleaning Robot$q$, $q$Robot de limpieza 4 en 1 para espacios pequeños y medianos: barrido, aspirado, fregado y extracción de agua, con separación húmedo-seco y hasta 1.100 m²/h.$q$, $q$4-in-1 cleaning robot for small and medium spaces: sweeping, vacuuming, scrubbing and water extraction, with dry/wet separation and up to 1,100 m²/h.$q$,
  $q$KLEENBOT C40 es un robot de limpieza autónoma 4 en 1 para espacios interiores pequeños y medianos. Su sistema de tres cepillos separa residuos secos y húmedos para evitar la contaminación cruzada, y su succión de hasta 23.500 Pa seca el piso tras el fregado. Incluye tanque de agua limpia de 16 L, batería LFP de 25,6 V y 50 Ah de cambio rápido, y pantalla táctil de 11,6 pulgadas.$q$, $q$KLEENBOT C40 is a 4-in-1 autonomous cleaning robot for small and medium indoor spaces. Its three-brush system separates dry and wet debris to avoid cross-contamination, and suction of up to 23,500 Pa dries the floor after scrubbing. It includes a 16 L clean-water tank, a 25.6 V, 50 Ah LFP battery with quick-swap design, and an 11.6-inch touchscreen.$q$, $j$[{"clave":"Modos de limpieza","valor":"Barrido; barrido + aspirado; barrido + mopa seca; barrido + fregado; extracción de agua","grupo":"Rendimiento"},{"clave":"Eficiencia de limpieza","valor":"Hasta 1.100 m²/h","grupo":"Rendimiento"},{"clave":"Área de limpieza","valor":"Hasta 3.000 m² en aspirado y 2.500 m² en fregado","grupo":"Rendimiento"},{"clave":"Succión","valor":"Hasta 23.500 Pa","grupo":"Rendimiento"},{"clave":"Ancho de limpieza","valor":"Barrido: 560 mm (con dos cepillos laterales); aspirado y fregado: 400 mm","grupo":"Rendimiento"},{"clave":"Recolección","valor":"Bolsa de 8 L y contenedor separado de 0,7 L","grupo":"Rendimiento"},{"clave":"Tanque de agua limpia","valor":"16 L","grupo":"Rendimiento"},{"clave":"Autonomía","valor":"Barrido hasta 15 h; mopa seca hasta 10 h; aspirado hasta 6 h; fregado hasta 5 h","grupo":"Rendimiento"},{"clave":"Ruido","valor":"70 dB","grupo":"Rendimiento"},{"clave":"Velocidad de desplazamiento","valor":"0,8 m/s","grupo":"Rendimiento"},{"clave":"Alfombra","valor":"Hasta 10 mm de pelo","grupo":"Rendimiento"},{"clave":"Salto de desnivel (navegación)","valor":"35 mm","grupo":"Rendimiento"},{"clave":"Altura de obstáculos superables","valor":"15 mm (navegación, barrido + aspirado); 5 mm (barrido + fregado, no recomendado)","grupo":"Rendimiento"},{"clave":"Paso mínimo","valor":"65 cm de ancho y 75 cm de alto","grupo":"Rendimiento"},{"clave":"Pendiente","valor":"≤ 8° (solo navegación); ≤ 2° (tarea de limpieza)","grupo":"Rendimiento"},{"clave":"Batería","valor":"LFP, 25,6 V, 50 Ah, con cambio rápido","grupo":"Batería y carga"},{"clave":"Carga","valor":"Automática con base de carga (se compra aparte) o manual con el cargador incluido","grupo":"Batería y carga"},{"clave":"Entrada de carga","valor":"100-240 V~, 50/60 Hz","grupo":"Batería y carga"},{"clave":"Tiempo de carga","valor":"Aprox. 2 h","grupo":"Batería y carga"},{"clave":"Material","valor":"ABS y aleación de aluminio","grupo":"Hardware y navegación"},{"clave":"Posicionamiento","valor":"Fusión de sensores (LiDAR y VSLAM), precisión a nivel de centímetro","grupo":"Hardware y navegación"},{"clave":"Sensores","valor":"LiDAR (alcance ≤ 40 m), visión estéreo (170° horizontal), VSLAM, láser de línea, ultrasonido, cámara RGB, sensor de colisión, IMU","grupo":"Hardware y navegación"},{"clave":"Pantalla","valor":"11,6 pulgadas táctil, 1920 × 1080","grupo":"Hardware y navegación"},{"clave":"Interacción","valor":"Luz, táctil y avisos de voz","grupo":"Hardware y navegación"},{"clave":"Conectividad","valor":"Wi-Fi, ESP01 y 4G","grupo":"Hardware y navegación"},{"clave":"Sistema operativo","valor":"Linux (control) y Android (interacción)","grupo":"Sistema"},{"clave":"Idiomas de la app","valor":"Chino, inglés, japonés, coreano, francés, tailandés y alemán","grupo":"Sistema"},{"clave":"Funciones de la app","valor":"Limpieza inmediata, programada, manual y modo de enseñanza; reanudación por punto de corte y coordinación de varios equipos","grupo":"Sistema"},{"clave":"Operación","valor":"0 a 40 °C · 20 % a 80 % HR · interior, pisos duros y alfombra de pelo bajo ≤ 10 mm","grupo":"Ambiente"},{"clave":"Almacenamiento","valor":"-15 a 45 °C · 20 % a 80 % HR","grupo":"Ambiente"},{"clave":"Dimensiones del robot (An × Pr × Al)","valor":"616 × 550 × 690 mm","grupo":"Dimensiones y peso"},{"clave":"Peso del robot","valor":"70 kg con batería y tanques vacíos (solo robot)","grupo":"Dimensiones y peso"},{"clave":"Base de carga (An × Pr × Al)","valor":"534 × 225 × 407 mm · aprox. 20 kg","grupo":"Dimensiones y peso"}]$j$::jsonb,
  ARRAY[$q$Espacios interiores pequeños y medianos$q$, $q$Barrido, aspirado y fregado en un solo recorrido$q$, $q$Pisos duros interiores$q$, $q$Alfombras de pelo bajo de hasta 10 mm$q$, $q$Operación con recarga automática y cambio rápido de batería$q$]::TEXT[], ARRAY[$q$Small and medium indoor spaces$q$, $q$Sweeping, vacuuming and scrubbing in one pass$q$, $q$Indoor hard floors$q$, $q$Low-pile carpets up to 10 mm$q$, $q$Operation with automatic recharging and quick battery swap$q$]::TEXT[], $q$/assets/productos/importados/kleenbot-c40-robot-limpieza-autonoma/robot-producto-kleenbot-c40.webp$q$, ARRAY[$q$/assets/productos/importados/kleenbot-c40-robot-limpieza-autonoma/robot-producto-kleenbot-c40.webp$q$, $q$/assets/productos/importados/kleenbot-c40-robot-limpieza-autonoma/robot-galeria-kleenbot-c40-01.webp$q$]::TEXT[],
  $q$/assets/productos/importados/kleenbot-c40-robot-limpieza-autonoma/ficha-tecnica.pdf$q$, $j${"beneficios_es":["Separación de tres cepillos: residuos secos y húmedos no se mezclan","Secado inmediato tras el fregado con succión de hasta 23.500 Pa","Batería de 50 Ah de cambio rápido para operación casi continua","Tanque de aguas residuales desmontable y lavable","Percepción 3D con LiDAR, visión estéreo, láser de línea y ultrasonido"],"beneficios_en":["Three-brush system: dry and wet debris are kept apart","Immediate drying after scrubbing with suction up to 23,500 Pa","50 Ah quick-swap battery for near-continuous operation","Removable, washable wastewater tank","3D perception with LiDAR, stereo vision, line laser and ultrasonic sensors"],"valor_es":"KLEENBOT C40 reúne barrido, aspirado, fregado y extracción de agua en un equipo con tanque de 16 L y batería de cambio rápido para reducir las paradas por carga. Precio bajo cotización.","valor_en":"KLEENBOT C40 combines sweeping, vacuuming, scrubbing and water extraction in one machine, with a 16 L tank and a quick-swap battery to reduce stops for charging. Price on request.","seo_keywords_es":["KLEENBOT C40","C40 robot de limpieza","robot de limpieza 4 en 1","robot fregadora autónoma","robot de limpieza húmedo y seco","robot de limpieza para espacios medianos","KEENON C40"],"seo_keywords_en":["KLEENBOT C40","C40 cleaning robot","4-in-1 cleaning robot","autonomous scrubber robot","wet and dry cleaning robot","cleaning robot for medium spaces","KEENON C40"],"marca":"KEENON"}$j$::jsonb,
